DROP TABLE IF EXISTS `odds_snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `odds_snapshots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `match_id` bigint unsigned NOT NULL,
  `scraped_at` datetime(3) NOT NULL,
  `home_odds` decimal(10,3) DEFAULT NULL,
  `draw_odds` decimal(10,3) DEFAULT NULL,
  `away_odds` decimal(10,3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_odds_match_scrape` (`match_id`,`scraped_at`),
  KEY `ix_odds_scraped_at` (`scraped_at`),
  CONSTRAINT `fk_odds_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=767 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
