--
-- Table structure for table `premier_league_player_injuries`
--

DROP TABLE IF EXISTS `premier_league_player_injuries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `premier_league_player_injuries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `injury_scrape_id` bigint unsigned NOT NULL,
  `team_id` bigint unsigned NOT NULL,
  `player_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `injury` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `latest_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_premier_league_player_injuries_scrape_player` (`injury_scrape_id`,`team_id`,`player_name`),
  KEY `ix_premier_league_player_injuries_team_player` (`team_id`,`player_name`),
  CONSTRAINT `fk_premier_league_player_injuries_scrape` FOREIGN KEY (`injury_scrape_id`) REFERENCES `premier_league_team_injuries` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_premier_league_player_injuries_team` FOREIGN KEY (`team_id`) REFERENCES `premier_league_teams` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

