--
-- Table structure for table `premier_league_match_team_stats`
--

DROP TABLE IF EXISTS `premier_league_match_team_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `premier_league_match_team_stats` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `premier_league_match_id` bigint unsigned NOT NULL,
  `team_id` bigint unsigned NOT NULL,
  `side` enum('Home','Away') COLLATE utf8mb4_unicode_ci NOT NULL,
  `stats` json NOT NULL,
  `scraped_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pl_match_team_stats_side` (`premier_league_match_id`,`side`),
  KEY `ix_pl_match_team_stats_team` (`team_id`,`scraped_at`),
  CONSTRAINT `fk_pl_match_team_stats_match` FOREIGN KEY (`premier_league_match_id`) REFERENCES `premier_league_matches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pl_match_team_stats_team` FOREIGN KEY (`team_id`) REFERENCES `premier_league_teams` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3185 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

