DROP TABLE IF EXISTS `premier_league_matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `premier_league_matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `external_match_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `season` smallint unsigned NOT NULL,
  `matchweek` tinyint unsigned NOT NULL,
  `kickoff` datetime DEFAULT NULL,
  `kickoff_timezone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phase` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `period` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `result_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ground` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attendance` int unsigned DEFAULT NULL,
  `home_team_id` bigint unsigned NOT NULL,
  `away_team_id` bigint unsigned NOT NULL,
  `home_score` smallint unsigned DEFAULT NULL,
  `away_score` smallint unsigned DEFAULT NULL,
  `home_half_time_score` smallint unsigned DEFAULT NULL,
  `away_half_time_score` smallint unsigned DEFAULT NULL,
  `home_red_cards` tinyint unsigned DEFAULT NULL,
  `away_red_cards` tinyint unsigned DEFAULT NULL,
  `scraped_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pl_matches_external_id` (`external_match_id`),
  KEY `ix_pl_matches_season_week` (`season`,`matchweek`),
  KEY `ix_pl_matches_home_kickoff` (`home_team_id`,`kickoff`),
  KEY `ix_pl_matches_away_kickoff` (`away_team_id`,`kickoff`),
  CONSTRAINT `fk_pl_matches_away_team` FOREIGN KEY (`away_team_id`) REFERENCES `premier_league_teams` (`id`),
  CONSTRAINT `fk_pl_matches_home_team` FOREIGN KEY (`home_team_id`) REFERENCES `premier_league_teams` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

